Here is a complete, lightweight application built with **Node.js** and **Express**. 

It meets all your requirements:
1. Passwords are encrypted using **bcrypt** (salted and hashed).
2. The verification runs exclusively on the server.
3. Uploaded files are kept in a private directory and cannot be accessed via a static URL without authentication.

---

### Step 1: Project Setup

Create a new folder on your computer and open your terminal inside it:

```bash
mkdir secure-share
cd secure-share
npm init -y
```

Install the required packages:
```bash
npm install express multer bcrypt uuid
```

---

### Step 2: Create the Server (`server.js`)

Create a file named `server.js` and paste the following code:

```javascript
const express = require('express');
const multer = require('multer');
const bcrypt = require('bcrypt');
const { v4: uuidv4 } = require('uuid');
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = 3000;

// Ensure uploads directory exists
const UPLOADS_DIR = path.join(__dirname, 'uploads');
if (!fs.existsSync(UPLOADS_DIR)) {
    fs.mkdirSync(UPLOADS_DIR);
}

// In-memory database (Use SQLite/MongoDB for persistence in production)
const filesDB = {};

// Middleware
app.use(express.urlencoded({ extended: true }));
app.use(express.static('public'));

// Configure Multer for secure file uploads
const storage = multer.diskStorage({
    destination: (req, file, cb) => cb(null, UPLOADS_DIR),
    filename: (req, file, cb) => {
        // Save using random IDs on the disk to prevent directory traversal
        cb(null, `${uuidv4()}${path.extname(file.originalname)}`);
    }
});
const upload = multer({ storage });

// 1. Upload Route
app.post('/upload', upload.single('file'), async (req, res) => {
    try {
        if (!req.file || !req.body.password) {
            return res.status(400).send('File and password are required.');
        }

        const shareId = uuidv4();
        // Salt and hash the password (Cost factor = 10)
        const passwordHash = await bcrypt.hash(req.body.password, 10);

        // Store metadata
        filesDB[shareId] = {
            diskFilename: req.file.filename,
            originalName: req.file.originalname,
            passwordHash: passwordHash
        };

        const shareUrl = `${req.protocol}://${req.get('host')}/share/${shareId}`;
        res.send(`
            <h2>File uploaded successfully!</h2>
            <p>Share this link: <a href="${shareUrl}">${shareUrl}</a></p>
            <a href="/">Upload another file</a>
        `);
    } catch (err) {
        res.status(500).send('Error uploading file.');
    }
});

// 2. Password Prompt Page
app.get('/share/:id', (req, res) => {
    const fileData = filesDB[req.params.id];
    if (!fileData) {
        return res.status(404).send('File not found or link expired.');
    }

    res.send(`
        <!DOCTYPE html>
        <html>
        <head><title>Protected Download</title></head>
        <body style="font-family: sans-serif; display: flex; justify-content: center; margin-top: 50px;">
            <div style="border: 1px solid #ccc; padding: 20px; border-radius: 8px;">
                <h3>Enter Password to Download:</h3>
                <p><strong>${fileData.originalName}</strong></p>
                <form action="/download/${req.params.id}" method="POST">
                    <input type="password" name="password" placeholder="Password" required style="padding: 8px;" />
                    <button type="submit" style="padding: 8px 12px;">Download</button>
                </form>
            </div>
        </body>
        </html>
    `);
});

// 3. Download Verification Route
app.post('/download/:id', async (req, res) => {
    const fileData = filesDB[req.params.id];

    if (!fileData) {
        return res.status(404).send('File not found.');
    }

    const { password } = req.body;

    // Server-side hash comparison
    const isMatch = await bcrypt.compare(password, fileData.passwordHash);

    if (isMatch) {
        const filePath = path.join(UPLOADS_DIR, fileData.diskFilename);
        // Securely stream the file to the client with its original name
        res.download(filePath, fileData.originalName);
    } else {
        res.status(401).send(`
            <h3>Incorrect password!</h3>
            <a href="/share/${req.params.id}">Try again</a>
        `);
    }
});

app.listen(PORT, () => {
    console.log(`Server running at http://localhost:${PORT}`);
});
```

---

### Step 3: Create the Frontend (`public/index.html`)

Create a folder named `public` and place an `index.html` file inside it:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Secure File Share</title>
    <style>
        body { font-family: sans-serif; display: flex; justify-content: center; margin-top: 50px; }
        .card { border: 1px solid #ddd; padding: 24px; border-radius: 8px; width: 320px; }
        .input-group { margin-bottom: 15px; }
        label { display: block; margin-bottom: 5px; font-weight: bold; }
        input[type="file"], input[type="password"] { width: 100%; box-sizing: border-box; }
        button { width: 100%; padding: 10px; background: #0066cc; color: #fff; border: none; border-radius: 4px; cursor: pointer; }
    </style>
</head>
<body>
    <div class="card">
        <h2>Upload & Protect</h2>
        <form action="/upload" method="POST" enctype="multipart/form-data">
            <div class="input-group">
                <label for="file">Choose file:</label>
                <input type="file" name="file" id="file" required>
            </div>
            <div class="input-group">
                <label for="password">Set a password:</label>
                <input type="password" name="password" id="password" required>
            </div>
            <button type="submit">Upload & Get Link</button>
        </form>
    </div>
</body>
</html>
```

---

### How to Run:

1. In your terminal, run:
   ```bash
   node server.js
   ```
2. Open your browser and navigate to: `http://localhost:3000`
3. Upload a file and pick a password.
4. Copy the generated link (e.g., `http://localhost:3000/share/xxxx-xxxx`).
5. Open an Incognito/Private window, visit the link, and verify that the file downloads **only** when the correct password is typed.

### Why this satisfies your requirements:
* **Hashed Storage**: The password is run through `bcrypt.hash()` before touching any object or database. The plain text password is discarded immediately.
* **No Client Leakage**: The hash is never sent to the `/share/:id` page. The browser only submits the password guess to `/download/:id`, where `bcrypt.compare()` validates it on the server.
* **Blocked Direct Access**: The `uploads/` directory is **not** served statically through `express.static()`. Files can strictly only be streamed via `res.download()` once the `isMatch` conditional passes.

